return [{json: {
  "actor": "html-markdown-batch",
  "runId": "SYNTHETIC-html-markdown-batch",
  "status": "SUCCEEDED",
  "rows": [
    {
      "markdown": "| Component | Status |\n| --- | --- |\n| Parser | Ready |\n| Exporter | Pending |"
    }
  ],
  "actId": "l0FzouietCktp3hSV"
}}];

const entries = $input.all();
const jobs = $('Trusted job reference').all(0, $runIndex);
if (entries.length !== 1 || jobs.length !== 1) throw new Error('Expected one receipt and one job reference');
const expectedRunId = jobs[0].json.expectedRunId;
const receipt = entries[0].json;
if (typeof expectedRunId !== 'string' || !expectedRunId.trim() || expectedRunId.trim() !== expectedRunId ||
    receipt.runId !== expectedRunId || receipt.actId !== "l0FzouietCktp3hSV" || receipt.actor !== "html-markdown-batch" ||
    receipt.status !== 'SUCCEEDED') throw new Error('Actor, run or terminal status mismatch');
const {runId, rows} = receipt;

if (!Array.isArray(rows) || !rows.length) throw new Error('No delivered rows to hand off');
return rows.map(row => {
  if (typeof row.markdown === 'string' && row.markdown.trim()) {
    return {json:{runId, markdown:row.markdown}};
  }
  throw new Error('Invalid row for this Actor');
});
